package com.example.smartexpenseanalyzer.service;
import com.example.smartexpenseanalyzer.model.*; import com.example.smartexpenseanalyzer.repository.ExpenseRepository; import org.springframework.stereotype.Service; import java.util.*; import java.math.BigDecimal;
@Service public class ExpenseService { private final ExpenseRepository repository; public ExpenseService(ExpenseRepository r){repository=r;} public void validateAmount(BigDecimal amount){if(amount==null||amount.signum()<=0||amount.scale()>2)throw new IllegalArgumentException("Amount must be positive and have no more than two decimal places");} public List<Expense> forUser(AppUser user){return repository.findByUserOrderByDateDesc(user);} public Optional<Expense> findOwned(Long id,AppUser user){return repository.findByIdAndUser(id,user);} public Expense save(Expense expense){return repository.save(expense);} public List<Expense> saveAll(Iterable<Expense> items){return repository.saveAll(items);} public void delete(Expense expense){repository.delete(expense);} public void deleteAll(Iterable<Expense> items){repository.deleteAll(items);} public List<Expense> all(){return repository.findAllByOrderByDateDesc();} }
